<script>
	import { actionPlans } from '$lib/mipg-new-data.js';
	let status = 'Todos';
	$: filtered = actionPlans.filter((item) => status === 'Todos' || item.status === status);
</script>
<main class="px-4 py-8 sm:px-6 lg:px-10"><div class="mx-auto max-w-7xl space-y-6"><section class="glass-3 rounded-2xl p-6"><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-primary text-xs font-bold uppercase tracking-[0.2em]">MIPG</p><h1 class="mt-2 text-3xl font-bold text-gray-900">Planes de acción</h1><p class="mt-2 text-sm text-gray-600">Gestiona compromisos, responsables, fechas y avance.</p></div><button type="button" class="bg-primary rounded-lg px-4 py-2 text-sm font-semibold text-white">+ Nuevo plan</button></div></section><section class="glass-3 rounded-xl p-5"><div class="flex flex-wrap gap-2" role="tablist" aria-label="Filtros de planes">{#each ['Todos', 'Pendiente', 'En curso', 'Completado'] as option (option)}<button type="button" class="rounded-lg px-3 py-2 text-xs font-semibold" class:bg-blue-50={status === option} class:text-blue-700={status === option} class:text-gray-600={status !== option} onclick={() => (status = option)}>{option}</button>{/each}</div></section><section class="glass-3 overflow-x-auto rounded-xl p-4"><table class="min-w-[850px] w-full text-sm"><thead><tr class="border-b border-gray-200 text-left text-xs uppercase tracking-wide text-gray-500"><th class="px-4 py-3">Acción</th><th class="px-4 py-3">Proceso</th><th class="px-4 py-3">Responsable</th><th class="px-4 py-3">Estado</th><th class="px-4 py-3">Avance</th><th class="px-4 py-3">Fecha límite</th></tr></thead><tbody>{#each filtered as item (item.title)}<tr class="border-b border-gray-200/70"><td class="px-4 py-4 font-semibold text-gray-800">{item.title}</td><td class="px-4 py-4 text-gray-600">{item.process}</td><td class="px-4 py-4 text-gray-600">{item.owner}</td><td class="px-4 py-4"><span class="rounded-full bg-blue-100 px-2 py-1 text-xs font-semibold text-blue-700">{item.status}</span></td><td class="px-4 py-4"><div class="flex items-center gap-2"><div class="h-2 w-24 rounded-full bg-gray-200"><div class="h-2 rounded-full bg-emerald-500" style={`width: ${item.progress}%`}></div></div><span class="text-xs">{item.progress}%</span></div></td><td class="px-4 py-4 text-gray-500">{item.due}</td></tr>{/each}</tbody></table></section></div></main>
